-- Source: MotherDuck thyroid_canonical_publication_v1_0.manuscript_workspace.ete_manuscript_analytic_v3
-- Captured: 2026-05-06 for THY-19 BQ migration

CREATE VIEW manuscript_workspace.ete_manuscript_analytic_v3 AS SELECT v2.*, f.ete_grade_fresh_llm, f.has_gross_fresh, f.has_micro_fresh, f.has_absent_fresh, f.fresh_evidence_quotes, f.fresh_best_confidence, f.fresh_ajcc8_implications, f.n_fresh_mentions AS llm_fresh_mention_count, CASE  WHEN (((v2.ete_grade_final IS NOT NULL) AND (v2.ete_grade_final != 'unspec_remaining'))) THEN (v2.ete_grade_final) WHEN (f.has_gross_fresh) THEN ('gross') WHEN (f.has_micro_fresh) THEN ('microscopic') WHEN (f.has_absent_fresh) THEN ('none') WHEN ((v2.ete_grade_final = 'unspec_remaining')) THEN ('unspec_remaining') ELSE NULL END AS ete_grade_final_v3, CASE  WHEN (((v2.ete_grade_final IS NOT NULL) AND (v2.ete_grade_final != 'unspec_remaining'))) THEN (v2.ete_grade_source) WHEN ((f.has_gross_fresh OR f.has_micro_fresh)) THEN ('llm_fresh_subgrade') WHEN (f.has_absent_fresh) THEN ('llm_fresh_absent') WHEN ((f.ete_grade_fresh_llm = 'unable_to_determine')) THEN ('llm_unable') WHEN ((v2.ete_grade_final = 'unspec_remaining')) THEN ('unresolved') ELSE NULL END AS ete_grade_source_v3 FROM manuscript_workspace.ete_manuscript_analytic_v2 AS v2 LEFT JOIN manuscript_workspace.ete_llm_fresh_subgrade_patient_v1 AS f ON ((CAST(f.research_id AS VARCHAR) = CAST(v2.research_id AS VARCHAR)));
